// Two automated runs per day. Each run uses one SerpAPI (Google) query
// and one LinkedIn guest keyword search, rotating focus areas per slot so
// consecutive runs cover different ground without burning SerpAPI quota.
const googleQueries = [
  'site:linkedin.com/jobs "Customer Operations" OR "Customer Service Lead" ("UAE" OR "Abu Dhabi" OR "Dubai")',
  'site:linkedin.com/jobs ("Systems Architect" OR "Solutions Architect") ("UAE" OR "Remote")',
  'site:linkedin.com/jobs ("Support Automation" OR "Process Optimization") ("Abu Dhabi" OR "Dubai")',
  'site:linkedin.com/jobs ("AI Automation" OR "Workflow Automation") ("UAE" OR "GCC" OR "Remote")',
  'site:linkedin.com/jobs "Operations Manager" ("Health Insurance" OR "Medical") "UAE"',
  'site:linkedin.com/jobs ("Customer Experience" OR "CX Lead") ("Abu Dhabi" OR "Dubai")'
];

const linkedinKeywords = [
  'Customer Operations',
  'Customer Service Lead',
  'Systems Automation',
  'Process Optimization',
  'Customer Experience',
  'Operations Manager'
];

const now = new Date();
const slot = Math.floor(now.getTime() / (12 * 3600 * 1000)) % googleQueries.length;

return [{
  json: {
    google_query: googleQueries[slot],
    linkedin_keyword: linkedinKeywords[slot % linkedinKeywords.length],
    run_slot: slot,
    timestamp: now.toISOString()
  }
}];

// SerpAPI returns structured results — no HTML scraping, no CAPTCHA.
const payload = $input.first().json || {};
const results = Array.isArray(payload.organic_results) ? payload.organic_results : [];
const jobs = [];
const seen = new Set();

for (const r of results) {
  const link = (r && r.link) || '';
  const m = link.match(/linkedin\.com\/jobs\/view\/([^"&?\/\s]+)/);
  if (!m) continue;
  const numeric = (String(m[1]).match(/\d{5,}/g) || []).pop() || '';
  if (!numeric || seen.has(numeric)) continue;
  seen.add(numeric);
  jobs.push({
    external_id: `li-${numeric}`,
    job_id: numeric,
    url: `https://www.linkedin.com/jobs/view/${numeric}`,
    source: 'google_serpapi'
  });
}

return [{ json: { source: 'google_serpapi', jobs } }];

// Public LinkedIn listing page — newest first, last 7 days.
const item = $input.first().json || {};
const html = item.data || '';
const jobs = [];
const seen = new Set();

for (const re of [/\/jobs\/view\/(\d+)/g, /jobPosting:(\d+)/g]) {
  let m;
  while ((m = re.exec(html)) !== null) {
    if (seen.has(m[1])) continue;
    seen.add(m[1]);
    jobs.push({
      external_id: `li-${m[1]}`,
      job_id: m[1],
      url: `https://www.linkedin.com/jobs/view/${m[1]}`,
      source: 'linkedin_public'
    });
  }
}

return [{ json: { source: 'linkedin_public', jobs } }];

// Union both sources, dedupe by LinkedIn job id, cap the batch so a
// single run stays polite to the guest API and cheap to review.
const MAX_JOBS_PER_RUN = 15;
const all = $input.all().flatMap(i => (i.json && i.json.jobs) || []);
const seen = new Set();
const jobs = [];

for (const job of all) {
  if (!job || !job.job_id || seen.has(job.job_id)) continue;
  seen.add(job.job_id);
  jobs.push(job);
  if (jobs.length >= MAX_JOBS_PER_RUN) break;
}

return jobs.map(j => ({ json: j }));

// Extract details for EVERY fetched posting (not just the first).
const urls = $('Dedupe & Cap').all();
const items = $input.all();
const out = [];

function stripTags(s) {
  return s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

function decodeEntities(s) {
  return s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"');
}

for (let i = 0; i < items.length; i++) {
  const item = items[i].json || {};
  const prev = (urls[i] && urls[i].json) || {};
  const html = item.data || '';
  if (!html || item.error) continue;

  let title = '';
  const titleMatch = html.match(/<h2[^>]*class="[^"]*top-card-layout__title[^"]*"[^>]*>([\s\S]*?)<\/h2>/)
    || html.match(/<h1[^>]*class="[^"]*top-card-layout__title[^"]*"[^>]*>([\s\S]*?)<\/h1>/)
    || html.match(/<title>([^|<]+)/);
  if (titleMatch) title = decodeEntities(stripTags(titleMatch[1]));

  let company = '';
  const companyMatch = html.match(/<a[^>]*class="[^"]*topcard__org-name-link[^"]*"[^>]*>([\s\S]*?)<\/a>/)
    || html.match(/"companyName"\s*:\s*"([^"]+)"/);
  if (companyMatch) company = decodeEntities(stripTags(companyMatch[1]));

  let location = '';
  const locMatch = html.match(/<span[^>]*class="[^"]*topcard__flavor--bullet[^"]*"[^>]*>([\s\S]*?)<\/span>/)
    || html.match(/<span[^>]*class="[^"]*topcard__flavor[^"]*"[^>]*>\s*([^<]+)/);
  if (locMatch) location = decodeEntities(stripTags(locMatch[1]));

  let description = '';
  const descMatch = html.match(/<div[^>]*class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/)
    || html.match(/<div[^>]*class="[^"]*description__text[^"]*"[^>]*>([\s\S]*?)<\/section/);
  if (descMatch) {
    description = decodeEntities(descMatch[1]).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }

  let workplace = '';
  const wpMatch = html.match(/"workplaceType"\s*:\s*"([^"]+)"/)
    || html.match(/<span[^>]*class="[^"]*workplace-type[^"]*"[^>]*>([^<]+)/);
  if (wpMatch) workplace = wpMatch[1].trim();

  if (!title && !description) continue;

  out.push({
    json: {
      external_id: prev.external_id || '',
      url: prev.url || '',
      source: prev.source || 'linkedin_public',
      job_title: title || 'Unknown Role',
      company: company || 'Unknown Company',
      location: location,
      workplace_type: workplace,
      description: description.substring(0, 8000),
      raw_description: description.substring(0, 8000)
    }
  });
}

return out;

// One request to the bridge carries the whole batch; the bridge dedupes
// against PostgreSQL and sends one Approve/Ignore card per new job.
const jobs = $input.all().map(i => i.json).filter(j => j && j.external_id);
return [{ json: { jobs } }];

const res = $input.first().json || {};
const summary = {
  status: res.status || 'UNKNOWN',
  inserted: res.inserted || 0,
  duplicates: res.duplicates || 0,
  failed: res.failed || 0,
  timestamp: new Date().toISOString()
};
console.log('Discovery run complete:', JSON.stringify(summary));
return [{ json: summary }];
